************************************************************************
*                                                                      *
      subroutine dwbaD
*                                                                      *
*       data base of DWBA results                                      *
*       modified by S.Hashimoto on 2014/02/19                          *
*                                                                      *
*        called from: dwbain                                           *
*                                                                      *
*       ninich : maximum number of initial channel                     *
*       nfinch : maximum number of final channel                       *
*       nenep  : maximum number of incident energy point               *
*       nthmx  : maximum number of scattering angle point              *
*                                                                      *
*       DPINI(N,*) : N=1 : atomic mass of projectile                   *
*                     =2 : atomic number of projectile                 *
*                     =3 : atomic mass of target                       *
*                     =4 : atomic number of target                     *
*                     =5 : number of final channels                    *
*                                                                      *
*       DPFIN(N,*) : N=1 : number of incident energy point             *
*                     =2 : Q-value of the process [MeV]                *
*                     =3 : energy width of the process [MeV]           *
*                     =4 : particle number of the final channel        *
*                     =5 : atomic mass of ejectile                     *
*                     =6 : atomic number of ejectile                   *
*                     =7 : atomic mass of residual nucleus             *
*                     =8 : atomic number of residual nucleus           *
*                                                                      *
*       SXSDWBA(N,*) : N=1 : integrated cross section [mb]             *
*                       =2 : incident energy [MeV]                     *
*       THPD(N,*) : N=1 : minimum emission angle of data [deg]         *
*                    =2 : maximum emission angle of data [deg]         *
*                    =3 : difference of data [deg]                     *
*                                                                      *
************************************************************************

*-----------------------------------------------------------------------

      implicit real*8 (a-h,o-z)

*-----------------------------------------------------------------------

      parameter (ninich=20,nfinch=17,nenep=10,nthmx=181)
      dimension DPINI(5,ninich),DPFIN(8,nfinch,ninich)
      dimension SXSDWBA(2,nenep,nfinch,ninich)
      dimension THPD(3,nenep,nfinch,ninich)
      dimension XSDWBA(nthmx,nenep,nfinch,ninich)
